#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> parent;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    parent.resize(n + 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    bool cycle = false;
    for (const vector<long long>& e : edges) {
        int a = findRoot((int)e[0]), b = findRoot((int)e[1]);
        if (a == b) {
            cycle = true;
            break;
        }
        parent[a] = b;
    }
    cout << (cycle ? "yes" : "no") << "\n";

    return 0;
}

